import{_ as p,a0 as l,w as o,s as d,ao as c,I as e,x as a,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 watch 和 tail 命令監視 Linux 上的活動 | LCTT x X-CMD","titleTemplate":false,"description":"使用 watch 和 tail 命令監視 Linux 上的活動 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 watch 和 tail 命令監視 Linux 上的活動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 watch 和 tail 命令監視 Linux 上的活動 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20200303 Watching activity on Linux with watch and tail commands","title":"使用 watch 和 tail 命令監視 Linux 上的活動","tag":"202205","desc":""},"relativePath":"202205/20200303 Watching activity on Linux with watch and tail commands.md","filePath":"[post].md"}'),h={name:"202205/20200303 Watching activity on Linux with watch and tail commands.md"};function r(g,s,u,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="使用-watch-和-tail-命令監視-linux-上的活動" tabindex="-1">使用 watch 和 tail 命令監視 Linux 上的活動 <a class="header-anchor" href="#使用-watch-和-tail-命令監視-linux-上的活動" aria-label="Permalink to “使用 watch 和 tail 命令監視 Linux 上的活動”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/07/091736ja5yt2yottef0kl4.jpg" alt=""></p><blockquote><p>watch 和 tail 命令可以幫助監視 Linux 系統上的活動。本文介紹了這兩個命令的一些有用的使用方法。</p></blockquote><p><code>watch</code> 和 <code>tail</code> 命令為持續監視 Linux 系統上的活動提供了一些有趣的選項。</p><p>也就是説，你可以通過 <code>watch</code> 來顯示誰已登錄，並隨着用户登錄和註銷不斷更新，而不是僅僅提出問題並獲得答案（例如詢問 <code>who</code> 並獲取當前登錄用户的列表）。</p><p>使用 <code>tail</code>，你可以顯示文件的底部並在添加內容時查看內容。這種監控一般非常有用，並且比定期運行命令所需的工作更少。</p><h3 id="使用-watch-命令" tabindex="-1">使用 watch 命令 <a class="header-anchor" href="#使用-watch-命令" aria-label="Permalink to “使用 watch 命令”">​</a></h3><p>使用 <code>watch</code> 的最簡單示例之一是使用命令 <code>watch who</code>。你會看到一個列表，其中顯示了誰登錄了，以及他們登錄的時間和登錄位置。請注意，默認設置是每兩秒更新一次顯示（左上角），日期和時間（右上角）將按該間隔自行更新。用户列表將隨着用户登錄和註銷而增長和縮小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch who</span></span></code></pre></div><p>此命令將顯示如下所示的登錄列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 2.0s: who                              dragonfly: Thu Feb 27 10:52:00 2020</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nemo     pts/0        2020-02-27 08:07 (192.168.0.11)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span></code></pre></div><p>你可以通過添加 <code>-n</code> 選項（例如 <code>-n 10</code>）來修改更新間的不同秒數，以修改更新間隔，從而獲取較少的更新頻率。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 10 who</span></span></code></pre></div><p>上述命令將以新的間隔顯示，並且顯示的時間更新頻率較低，從而使顯示時間與所選間隔保持一致。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 10.0s: who                             dragonfly: Thu Feb 27 11:05:47 2020</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nemo     pts/0        2020-02-27 08:07 (192.168.0.11)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span></code></pre></div><p>如果你希望僅查看命令的輸出，而不是標題（前 2 行），則可以通過添加 <code>-t</code>（無標題）選項來省略這些行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -t who</span></span></code></pre></div><p>然後，你的屏幕將顯示如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nemo     pts/0        2020-02-27 08:07 (192.168.0.11)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span></code></pre></div><p>如果每次運行監視的命令時，輸出都是相同的，則只有標題行（如果未省略）會更改。其餘顯示的信息將保持不變。</p><p>如果你希望 <code>watch</code> 命令在它正在監視的命令的輸出發生更新後立即退出，則可以使用 <code>-g</code>（將其視為“<ruby>離開<rt>go away</rt></ruby>”）選項。例如，如果你只是在等待其他人開始登錄系統，則可以選擇執行此操作。</p><p>你還可以使用 <code>-d</code>（<ruby>差異<rt>differences</rt></ruby>）選項突出顯示顯示輸出中的更改。突出顯示只會持續一個間隔（默認為 2 秒），但有助於引起你對更新的注意。</p><p>下面是一個更復雜的示例，該示例使用 <code>watch</code> 命令顯示正在偵聽連接的服務及其使用的端口。雖然輸出不太可能更改，但它會提醒你任何新服務正在啓動或關閉。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch &#39;sudo lsof -i -P -n | grep LISTEN&#39;</span></span></code></pre></div><p>值得注意的是，正在運行的命令需要用引號擴起來，以確保不會將 <code>watch</code> 命令的輸出發送到 <code>grep</code> 命令。</p><p>使用 <code>watch -h</code> 命令將為你提供命令選項的列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -h</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span> watch [options] command</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -b, --beep             beep if command has a non-zero exit</span></span>
<span class="line"><span>  -c, --color            interpret ANSI color and style sequences</span></span>
<span class="line"><span>  -d, --differences[=&lt;permanent&gt;]</span></span>
<span class="line"><span>                         highlight changes between updates</span></span>
<span class="line"><span>  -e, --errexit          exit if command has a non-zero exit</span></span>
<span class="line"><span>  -g, --chgexit          exit when output from command changes</span></span>
<span class="line"><span>  -n, --interval &lt;secs&gt;  seconds to wait between updates</span></span>
<span class="line"><span>  -p, --precise          attempt run command in precise intervals</span></span>
<span class="line"><span>  -t, --no-title         turn off header</span></span>
<span class="line"><span>  -x, --exec             pass command to exec instead of &quot;sh -c&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -h, --help     display this help and exit</span></span>
<span class="line"><span> -v, --version  output version information and exit</span></span></code></pre></div><h3 id="使用-tail-f" tabindex="-1">使用 tail -f <a class="header-anchor" href="#使用-tail-f" aria-label="Permalink to “使用 tail -f”">​</a></h3><p><code>tail -f</code> 命令與 <code>watch</code> 有一些相同之處。它也會在添加文件時顯示文件的底部和其他內容。你不必一次又一次地運行 <code>tail</code> 命令，而是運行一個命令並獲得可重複更新顯示視圖的結果。例如，你可以使用如下命令查看系統日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f /var/log/syslog</span></span></code></pre></div><p>某些文件（如 <code>/var/log/wtmp</code>）不適合這種類型的處理，因為它們的格式不是普通文本文件，但是通過組合 <code>watch</code> 和 <code>tail</code>，你可以獲得類似的結果，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>watch &#39;who /var/log/wtmp | tail -20&#39;</span></span></code></pre></div><p>無論有多少用户仍處於登錄狀態，此命令都將只顯示最近的 5 次登錄。如果發生其他登錄，顯示結果將添加一行記錄並刪除頂行記錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 60.0s: who /var/log/wtmp | tail -5    dragonfly: Thu Feb 27 12:46:07 2020</span></span>
<span class="line"><span></span></span>
<span class="line"><span>shs      pts/0        2020-02-27 08:07 (192.168.0.5)</span></span>
<span class="line"><span>nemo     pts/1        2020-02-27 08:26 (192.168.0.5)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span>
<span class="line"><span>nemo     pts/1        2020-02-27 11:34 (192.168.0.5)</span></span>
<span class="line"><span>dory     pts/1        2020-02-27 12:14 (192.168.0.5)</span></span></code></pre></div><p>對你有時可能想要監視的信息，無論監視進程、登錄名還是系統資源，<code>watch</code> 和 <code>tail -f</code> 命令都可以提供自動更新視圖，從而使監視任務變得更加容易。</p><hr>`,36)),e("p",null,[s[1]||(s[1]=a("via: ",-1)),t(n,{href:"https://www.networkworld.com/article/3529891/watching-activity-on-linux-with-watch-and-tail-commands.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3529891/watching-activity-on-linux-with-watch-and-tail-commands.html",-1)])]),_:1})]),e("p",null,[s[6]||(s[6]=a("作者：",-1)),t(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),t(n,{href:"https://github.com/Starryi"},{default:i(()=>[...s[4]||(s[4]=[a("Starryi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const x=p(h,[["render",r]]);export{y as __pageData,x as default};
